using Crown.Core;

internal static class StageTwentyFourSpecs
{
    private static void Assert(bool value,string text){if(!value)throw new Exception(text);}
    private static (GameState S,Unit Ship,Unit Troop,int Target) Assault(UnitKind kind=UnitKind.Spearmen,string? model="line_infantry")
    {
        var s=StageTwentyTwoSpecs.Fixture();s.Relation(0,1).War=true;
        s.Player.Technologies.UnionWith(EpochCatalog.All.Take(11).SelectMany(e=>e.Technologies));for(int i=0;i<11;i++)s.Player.EpochChoices[i]=0;
        var ship=Engine.AddUnit(s,0,13*s.Width+12,UnitKind.Ship,"destroyer");var troop=Engine.AddUnit(s,0,s.Cities[0].Tile,kind,model);
        Assert(SeaTransport.Embark(s,troop.Id,ship.Id).Success,"Setup boarding failed");int target=s.Cities[0].Tile+1;s.Tiles[target].Owner=1;s.InvalidateLogistics();return(s,ship,troop,target);
    }
    private static Unit Enemy(GameState s,int target,double health=100,string model="hunters"){var e=Engine.AddUnit(s,1,target,UnitKind.Spearmen,model);e.Health=health;return e;}
    private static void Valid(GameState s)=>SaveGame.Deserialize(SaveGame.Serialize(s));
    private static (GameState S,Unit Ship,Unit Guard) Beach()
    {var(s,ship,u,t)=Assault();ship.Tile=u.Tile=15*s.Width+12;u.EmbarkedOnId=null;u.Tile=16*s.Width+12;u.Order=MilitaryOrder.Fortify;u.FortificationTurns=1;u.Actions=0;return(s,ship,u);}
    public static void Run(Action<string,Action> test)
    {
        test("Assault previews preserve state and expose the landing penalty",()=>{var(s,ship,u,t)=Assault();Enemy(s,t);string before=SaveGame.Serialize(s);var p=AmphibiousAssault.Preview(s,u.Id,t);Assert(p.Valid&&!p.Ranged&&p.Modifiers!.Any(m=>m.Contains("0,65"))&&SaveGame.Serialize(s)==before,"Preview mutation or hidden penalty");double sea=p.AttackStrength;u.EmbarkedOnId=null;u.Tile=s.Cities[0].Tile;u.Actions=u.MaxActions;Assert(Math.Abs(Engine.PreviewAttack(s,u.Id,t).AttackStrength*.65-sea)<.001,"Wrong strength");});
        test("Successful assault lands the original troop and charges the carrier",()=>{var(s,ship,u,t)=Assault();var e=Enemy(s,t,1);double moves=ship.Actions;Assert(AmphibiousAssault.Execute(s,u.Id,t).Success&&!s.Units.Contains(e)&&u.EmbarkedOnId==null&&u.Tile==t&&u.Actions==0&&ship.Actions==0,"Landing or costs wrong");Valid(s);});
        test("Repelled assault keeps survivors aboard with exactly forecast casualties",()=>{var(s,ship,u,t)=Assault(model:"hunters");var e=Enemy(s,t,100,"stellar_guard");var p=AmphibiousAssault.Preview(s,u.Id,t);Assert(AmphibiousAssault.Execute(s,u.Id,t).Success&&u.EmbarkedOnId==ship.Id&&u.Tile==ship.Tile&&Math.Abs(u.Health-(100-p.DamageToAttacker))<.001&&Math.Abs(e.Health-(100-p.DamageToTarget))<.001,"Forecast or retreat wrong");Valid(s);});
        test("Dead assault troops do not corrupt surviving passenger links",()=>{var(s,ship,u,t)=Assault(model:"hunters");u.Health=1;Enemy(s,t,100,"stellar_guard");var other=Engine.AddUnit(s,0,s.Cities[0].Tile,UnitKind.Spearmen);SeaTransport.Embark(s,other.Id,ship.Id);Assert(AmphibiousAssault.Execute(s,u.Id,t).Success&&!s.Units.Contains(u)&&other.EmbarkedOnId==ship.Id,"Manifest casualty wrong");Valid(s);});
        test("Several defenders require separate assaults",()=>{var(s,ship,u,t)=Assault();Enemy(s,t,1);var second=Enemy(s,t,1);Assert(AmphibiousAssault.Execute(s,u.Id,t).Success&&s.Units.Contains(second)&&u.EmbarkedOnId==ship.Id,"Defender stack bypassed");Valid(s);});
        test("Settlers scouts and artillery cannot assault a defended coast",()=>{foreach(var kind in new[]{UnitKind.Settler,UnitKind.Scout,UnitKind.Catapult}){var(s,ship,u,t)=Assault(kind,kind==UnitKind.Scout?"tribal_scout":kind==UnitKind.Catapult?"cannon":null);Enemy(s,t);string before=SaveGame.Serialize(s);Assert(!AmphibiousAssault.Execute(s,u.Id,t).Success&&SaveGame.Serialize(s)==before,"Wrong role assaulted");}});
        test("Invalid assault targets reject atomically",()=>{for(int mode=0;mode<7;mode++){var(s,ship,u,t)=Assault();Enemy(s,t);switch(mode){case 0:ship.Actions=0;break;case 1:t=ship.Tile;break;case 2:t=s.Cities[2].Tile;break;case 3:s.Relation(0,1).War=false;break;case 4:s.Tiles[t].Explored=false;break;case 5:s.Tiles[t].Terrain=Terrain.Mountain;break;case 6:u.EmbarkedOnId=null;break;}string before=SaveGame.Serialize(s);Assert(!AmphibiousAssault.Execute(s,u.Id,t).Success&&SaveGame.Serialize(s)==before,"Invalid assault changed state");}});
        test("Assault owner guards prevent foreign manifest control",()=>{var(s,ship,u,t)=Assault();Enemy(s,t);string before=SaveGame.Serialize(s);Assert(!AmphibiousAssault.Execute(s,u.Id,t,1).Success&&SaveGame.Serialize(s)==before,"Owner spoof accepted");});
        test("A repelled passenger cannot repeat its assault within the same turn",()=>{var(s,ship,u,t)=Assault(model:"hunters");Enemy(s,t,100,"stellar_guard");Assert(AmphibiousAssault.Execute(s,u.Id,t).Success&&ship.Actions==0,"Assault did not occupy carrier");string before=SaveGame.Serialize(s);Assert(!AmphibiousAssault.Execute(s,u.Id,t).Success&&SaveGame.Serialize(s)==before,"Same-turn repeat assault accepted");});
        test("Empty shores require normal exhausted landing",()=>{var(s,ship,u,t)=Assault();Assert(!AmphibiousAssault.Execute(s,u.Id,t).Success&&SeaTransport.Disembark(s,u.Id,t).Success&&u.Actions==0,"Empty shore granted action");});
        test("Coastal assault captures weakened cities with normal occupation",()=>{var(s,ship,u,t)=Assault();var c=s.Cities[1];ship.Tile=u.Tile=13*s.Width+20;c.Health=1;Assert(AmphibiousAssault.Preview(s,u.Id,c.Tile).CanCapture&&AmphibiousAssault.Execute(s,u.Id,c.Tile).Success&&c.Owner==0&&u.EmbarkedOnId==null&&u.Tile==c.Tile&&u.Actions==0&&c.OriginalOwner==1,"City capture wrong");Valid(s);});
        test("City garrisons must fall before their city can be captured",()=>{var(s,ship,u,t)=Assault();var c=s.Cities[1];ship.Tile=u.Tile=13*s.Width+20;c.Health=1;Enemy(s,c.Tile,1);Assert(!AmphibiousAssault.Preview(s,u.Id,c.Tile).CanCapture&&AmphibiousAssault.Execute(s,u.Id,c.Tile).Success&&c.Owner==1&&u.EmbarkedOnId==ship.Id,"Garrison bypassed");Valid(s);});
        test("Assault respects a third party's peaceful territory",()=>{var(s,ship,u,t)=Assault();Enemy(s,t);s.Tiles[t].Owner=2;Assert(!AmphibiousAssault.Preview(s,u.Id,t).Valid,"Neutral border violated");});
        test("AI performs favorable assaults and never commandeers the player",()=>{var(s,ship,u,t)=Assault();var e=Enemy(s,t,1);string before=SaveGame.Serialize(s);Engine.RunTransportAi(s,0);Assert(SaveGame.Serialize(s)==before,"Player automated");ship.Owner=u.Owner=1;e.Owner=0;s.Tiles[t].Owner=0;Engine.RunTransportAi(s,1);Assert(u.EmbarkedOnId==null&&u.Tile==t&&u.Actions==0,"AI assault failed");Valid(s);});
        test("Three inland siege fronts stop actual economic repairs",()=>{var s=StageTwentyOneSpecs.Fixture();s.Relation(0,1).War=true;var c=s.Cities[0];c.Health=40;foreach(var t in World.Neighbors(s,c.Tile).Take(3))Enemy(s,t.Id);Assert(SiegeWarfare.Report(s,c).Encircled&&Engine.EndTurn(s).Success&&c.Health==40,"Besieged city healed");});
        test("Three troops stacked together form only one siege front",()=>{var s=StageTwentyOneSpecs.Fixture();s.Relation(0,1).War=true;var c=s.Cities[0];for(int i=0;i<3;i++)Enemy(s,World.Neighbors(s,c.Tile).First().Id);var r=SiegeWarfare.Report(s,c);Assert(r.Fronts==1&&!r.Encircled&&r.Repair==7,"Stack became encirclement");});
        test("Partial siege slows repairs and coastal encirclement requires naval closure",()=>{var s=StageTwentyTwoSpecs.Fixture();s.Relation(0,1).War=true;var c=s.Cities[0];foreach(var t in World.Neighbors(s,c.Tile).Where(t=>t.Passable).Take(2))Enemy(s,t.Id);Assert(SiegeWarfare.Report(s,c).Repair==2,"Partial siege ineffective");Enemy(s,World.Neighbors(s,c.Tile).First(t=>t.Passable&&!s.Units.Any(u=>u.Tile==t.Id)).Id);Assert(!SiegeWarfare.Report(s,c).Encircled,"Open sea ignored");Engine.AddUnit(s,1,13*s.Width+12,UnitKind.Ship,"coastal_galley");Assert(SiegeWarfare.Report(s,c).Encircled,"Naval closure ineffective");s.Relation(0,1).War=false;Assert(SiegeWarfare.Report(s,c).Repair==7,"Peace failed to lift siege");});
        test("Civilians escorts and severely wounded troops cannot besiege",()=>{var s=StageTwentyOneSpecs.Fixture();s.Relation(0,1).War=true;var c=s.Cities[0];var ring=World.Neighbors(s,c.Tile).ToArray();Engine.AddUnit(s,1,ring[0].Id,UnitKind.Settler);Engine.AddUnit(s,1,ring[1].Id,UnitKind.Scout);Enemy(s,ring[2].Id,24);Enemy(s,ring[3].Id).EscortCaravanId=42;Assert(SiegeWarfare.Report(s,c).Fronts==0,"Ineligible front counted");});
        test("Wall damage affects full campaigns while legacy defense stays unchanged",()=>{var s=StageTwentyOneSpecs.Fixture();var c=s.Cities[0];c.Buildings.Add("walls");c.Health=20;Assert(SiegeWarfare.WallBonus(s,c)<5,"Walls unaffected");s.EpochCampaign=false;Assert(SiegeWarfare.WallBonus(s,c)==10&&SiegeWarfare.Report(s,c).Repair==7,"Legacy changed");});
        test("Landing and full preparation establish a beachhead through ordinary turns",()=>{var(s,ship,u,t)=Assault();ship.Tile=u.Tile=15*s.Width+12;t=16*s.Width+12;Assert(SeaTransport.Disembark(s,u.Id,t).Success&&!SiegeWarfare.Beachheads(s,0).Any(),"Free beachhead");s.PendingEvent=null;Engine.EndTurn(s);Assert(Engine.SetMilitaryOrder(s,u.Id,MilitaryOrder.Fortify).Success&&!SiegeWarfare.Beachheads(s,0).Any(),"Skipped preparation");s.PendingEvent=null;Engine.EndTurn(s);Assert(SiegeWarfare.Beachheads(s,0).Any(g=>g.Id==u.Id)&&Engine.Supplied(s,u),"Prepared guard got no supply");Valid(s);});
        test("Beachheads supply two land steps without creating trade connections",()=>{var(s,ship,u)=Beach();var near=Engine.AddUnit(s,0,18*s.Width+12,UnitKind.Spearmen);var far=Engine.AddUnit(s,0,20*s.Width+12,UnitKind.Spearmen);Assert(SiegeWarfare.BeachheadSupplies(s,near)&&!SiegeWarfare.BeachheadSupplies(s,far)&&!Logistics.For(s,0).ConnectedCities.Contains(s.Cities[1].Id),"Range or trade leak");foreach(var tile in World.Neighbors(s,u.Tile).Where(x=>x.Passable))tile.Terrain=Terrain.Mountain;Assert(!SiegeWarfare.BeachheadSupplies(s,near),"Supplied over mountains");});
        test("Loss movement or enemy interdiction of the carrier immediately cuts a beachhead",()=>{for(int mode=0;mode<4;mode++){var(s,ship,u)=Beach();Assert(SiegeWarfare.BeachheadSupplies(s,u),"Invalid setup");switch(mode){case 0:ship.Tile=13*s.Width+12;break;case 1:s.Units.Remove(ship);break;case 2:Engine.AddUnit(s,1,15*s.Width+13,UnitKind.Ship,"carrack");break;case 3:ship.Health=39;break;}Assert(!SiegeWarfare.BeachheadSupplies(s,u),"Supply survived naval loss");}});
        test("Weakening or waking the entrenched infantry ends its beachhead",()=>{var(s,ship,u)=Beach();Assert(SiegeWarfare.BeachheadSupplies(s,u),"Invalid setup");u.Health=39;Assert(!SiegeWarfare.BeachheadSupplies(s,u),"Wounded guard supplied army");u.Health=100;Engine.WakeUnit(s,u.Id);Assert(!SiegeWarfare.BeachheadSupplies(s,u),"Abandoned position supplied army");});
        test("A beachhead cannot invent supply for its own carrier",()=>{var(s,ship,u)=Beach();s.Cities[0].Buildings.Remove(Navy.Port);s.InvalidateLogistics();Assert(!SiegeWarfare.BeachheadSupplies(s,u)&&!Navy.Supplied(s,ship),"Circular supply");});
        test("Assaults and sieges preserve deterministic save continuation",()=>{var(s,ship,u,t)=Assault();Enemy(s,t,1);AmphibiousAssault.Execute(s,u.Id,t);var copy=SaveGame.Deserialize(SaveGame.Serialize(s));for(int i=0;i<2;i++){s.PendingEvent=copy.PendingEvent=null;Engine.EndTurn(s);Engine.EndTurn(copy);Assert(SaveGame.Serialize(s)==SaveGame.Serialize(copy),"Future diverged");}Assert(copy.Version==SaveGame.CurrentVersion,"Unexpected version");});
    }
}
